script:
function applyStyle() {    
// Your CSS as text
var styles = `
     #page-Tree\\/Task .container.page-body {
        max-height: calc(100vh - var(--navbar-height) - 65px);
        overflow-y: hidden;
    }
    @media (min-width: 576px) {
      .tree-header {
        max-width: 510px;
      }
    }
    @media (min-width: 768px) {
        .column-resizer {
            cursor: col-resize;
            width: 3px;
            position: absolute;
            right: 0;
            top: 0;
            height: 100%;
            z-index: 1;
            background-color: var(--bg-color);
        }
        #page-Tree\\/Task div.page-form.row > div:nth-child(6),
        #page-Tree\\/Task div.page-form.row > div:nth-child(7) {
            flex: 0 0 8.33333333% !important;
            max-width: 8.33333333% !important;
        }
    }
    @media (min-width: 768px) {
      .tree-header {
        max-width: 810px;
      }
      body.full-width .tree-header.header-fixed {
        width: calc(90% - 30px);
      }
      body.full-width .tree-header {
        width: 100%;
        max-width: 100%;
      }
    }
    @media (min-width: 992px) {
      .tree-header {
        max-width: 1060px;
      }
    }
    @media (min-width: 1200px) {
      .tree-header {
        max-width: 1260px;
      }
    }
    .tree-table, .tree-header {
        overflow-x: scroll !important;    // Прокрутка по горизонтали влево-вправо 
    }
    .tree-header {
        -webkit-box-shadow: 0 5px 25px rgba(0, 0, 0, 0.15);
        box-shadow: 0 5px 25px rgba(0, 0, 0, 0.15);
        background: var(--bg-color);
        width: 100%;
    }
    .tree-header.header-fixed {
        position: fixed;
        z-index: 9;
        top: 48px;
        width: calc(100% - 30px);
    }
    .tree {
        padding: var(--padding-sm) 0px 0px 0px;
    }
    .header .tree-link.header {
        justify-content: center;
        font-weight: 600;
    }
    .header-icon {
        /*padding: 5px 5px;*/
        margin: auto 5px;
    }
    .tree-table {
        height: calc(100vh - 230px);
    }
    .tree-table .tree {
        min-width: min-content;
    }
    .tree > .tree-link {
        min-height: 24px;
    }
    .tree li.tree-node {
        flex-wrap: wrap;
        margin: 0px !important;    
    }
    .tree-children .tree-link, .tree-children .details-area {
        border-top: 1px dashed gray;
    }
    .tree-row {
        display: flex;
        flex-wrap: nowrap;
        justify-content: space-between;
        min-width: fit-content;
    }
    .tree-node .tree-row {
        min-height: 27px;
        max-height: 27px;
    }
    .tree-link {
        white-space: normal;
        align-items: center;
        display: inline-flex;
        max-width: min(50vw, 600px);
        min-width: min(50vw, 600px);
        background: var(--bg-color);
        box-shadow: 1px 0px 3px -2px gray;
        flex: 5;
        z-index: 2;
        padding: 0px;
        width: 100%;
    }
    @media (min-width: 768px) {
        .tree > .tree-link {
            max-width: fit-content;
            min-width: fit-content;
        }
        .tree-link {
            position: sticky;
            left: 0px;
        }
    }
    .main-col {
        width: 100%;
        text-align: center;
    }
    .tree-label {
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
        max-width: 100%;
        vertical-align: middle;
        flex: 1;
        //min-width: 25vw;
    }
    .tree-label span {
        display: none;
    }
    .tree-node-toolbar {
        align-items: center;
        margin: auto;
        align-self: flex-end;
    }
    .details-area {
        /*max-width: 800px;*/
        display: inline-flex;
        justify-content: flex-end;
        align-items: stretch;
        white-space: normal;
        flex: 5;
    }
    .details-cell {
        margin: 0px 3px;
        min-width: 85px;
        max-width: 200px;
        flex: 1;
        text-align: center;
        font-size: var(--text-xs);
        font-weight: 400;
        display: flex;
        align-items: center;
        justify-content: center;
    }
    .tree-header .details-cell.header[data-field="hours"],
    .tree-row .details-cell.hours,
    .tree-header .details-cell.header[data-field="custom_include"],
    .tree-row .details-cell.timesheet {
        min-width : 35px;
        max-width : 35px;
    }
    .details-cell select {
        appearance: none;
        background: transparent;
        height: 100%;
        border: none;
        padding: 0 1em 0 0;
        margin: 0;
        width: 100%;
        outline: none;
    }
    .tree-row.edit .details-cell select {
        cursor: pointer;
    }
    .details-cell select:focus + .focus {
        position: absolute;
        top: -1px;
        left: -1px;
        right: -1px;
        bottom: -1px;
        border: 2px solid var(--select-focus);
        border-radius: inherit;
    }
    /* Цвет статуса */
    .details-cell.status.completed{
        color: var(--text-on-green);
        background-color: var(--bg-green);
    }
    .details-cell.status.overdue{
        color: var(--alert-text-danger);
        background-color: var(--alert-bg-danger);
    }
    .details-cell.status.cancelled{
        color: var(--text-on-light-gray);
        background-color: var(--bg-light-gray);
    }
    /*.details-cell.status.open{
        color: var(--text-on-light-gray);
        background-color: var(--bg-light-gray);
    }*/
    .details-cell.status.working{
        color: var(--text-on-blue);
        background-color: var(--bg-blue);
    }
    .details-cell.status.pending_review{
        color: var(--text-on-dark-blue);
        background-color: var(--bg-dark-blue);
    }
     /* Цвет приоритета */
    .details-cell .frappe-control[data-fieldtype=Select] {
        width: 100%;
        font-size: var(--text-xs);
    }
    .details-cell .frappe-control[data-fieldtype=Select] .control-input .select-icon {
        top: 0px;
        right: 0px;
    }
    .details-cell.priority.urgent{
        background: var(--bg-red);
        color: var(--text-on-red);
    }
    .details-cell.priority.high{
        color: var(--text-orange);
        background-color: var(--bg-orange);
    }
    .details-cell.priority.medium{
        color: var(--text-on-yellow);
        background-color: var(--bg-yellow);
    }
    .tree-table .form-group {
        margin: 0px !important;
    }
   .details-cell .form-group .form-control {
        border-radius: 0px;
        font-size: var(--text-xs);
        text-align: center;
    }
    .tree-table .form-group .clearfix, .tree-table .form-group .help-box {
        display: none;
    }
    .details-cell.progress {
        margin: auto 5px;
        justify-content: start;
    }
    .details-cell .progress-bar {
        height: 100%;
    }
    .tree-header .details-cell.header[data-field="expected_time"],
    .tree-row .details-cell.duration {
        min-width : 50px;
        max-width : 50px;
    }
    .details-cell.timesheet input {
        margin: 0px !important;
    }
    .details-cell.timesheet .checkbox {
        display: flex;
    }
    .details-cell.timesheet .label-area {
        display: none;
    }
    .tree-row.edit .details-cell.assign {
        cursor: pointer;
    }
    .tree-header .details-cell.header[data-field="_assign"],
    .tree-row .details-cell.assign {
        min-width : 100px;
        max-width : 100px;
    }
    .tree-header .details-cell.header[data-field="_user_tags"],
    .tree-row .details-cell.user_tag {
        min-width : 120px;
    }
    .tree-row .details-cell.user_tag .tag-pill {
        cursor: pointer;
    }
    .tree-row.edit .details-cell.exp_start_date, .tree-row.edit .details-cell.exp_end_date, .tree-row.edit .tree-label {
        cursor: text;
    }
    .tree-table .form-control {
        background-color: transparent;
        padding: 0px;
        font-size: var(--text-md);
    }
    .tree-table .form-control:focus, .details-cell:not(.progress):hover, .tree-link:hover,
    .tree-table .tree-link.hover, .tree-table .tree-row.hover {
        background-color: var(--control-bg);
    }
    .tree-table .tree-link:hover .tree-node-toolbar.btn-group {
        display: inline-flex !important;
    }
    .tree-table .tree-link:not(:hover) .tree-node-toolbar.btn-group {
        display: none !important;
    }
    .tree-table .tree-label.control input {
        text-overflow: ellipsis;
    }
    .list-assignments{
        justify-content: center;
    }
    .tree-children {
        min-width: 100%;
        box-sizing: content-box;
        padding-left: 0 !important;
    }
    /* Отступы для вложенных подзадач уровня 1, 2, 3 и далее*/
    .tree-children .tree-link {
        padding-left: calc(1 * var(--padding-xl)) !important;   
    }
    .tree-children .tree-children .tree-link {
        padding-left: calc(2 * var(--padding-xl)) !important;   
    }
    .tree-children .tree-children .tree-children .tree-link {
        padding-left: calc(3 * var(--padding-xl)) !important; 
    }
    .tree-children .tree-children .tree-children .tree-children .tree-link {
        padding-left: calc(4 * var(--padding-xl)) !important; 
    }
`

var styleSheet = document.createElement("style");
styleSheet.textContent = styles;
document.head.appendChild(styleSheet);
}

applyStyle();
